import { createRoot } from "react-dom/client";
import { type ComponentType, type ReactNode, useEffect, useState } from "react";
import {
    type AttachmentHandlerOpts,
    type MessageAttachment,
    type OpenAIAttachmentsGlobals,
    type OpenAIAttachmentsToolOutput,
    type OpenAIAttachmentsUnknownObject,
} from "@sierra/web";

// Runtime values for OpenAI integration
export const SET_GLOBALS_EVENT_TYPE = "openai:set_globals";

export class SetGlobalsEvent extends CustomEvent<{
    globals: Partial<OpenAIAttachmentsGlobals>;
}> {
    override readonly type = SET_GLOBALS_EVENT_TYPE;
}

// Hook to handle OpenAI attachments
export function useOpenAIAttachments() {
    const [attachments, setAttachments] = useState<MessageAttachment[]>([]);

    useEffect(() => {
        if (typeof window === "undefined" || !window.openai) {
            return;
        }

        const toolOutput = window.openai.toolOutput as OpenAIAttachmentsToolOutput | null;
        const customAttachments = toolOutput?.custom_attachments ?? [];

        // Convert OpenAI attachments to MessageAttachment format
        const converted: MessageAttachment[] = customAttachments.map(att => ({
            type: "custom" as const,
            data: att.data,
        }));

        setAttachments(converted);

        // Listen for updates to toolOutput
        const handleSetGlobals = (event: SetGlobalsEvent) => {
            const globals = event.detail.globals as Partial<
                OpenAIAttachmentsGlobals<
                    OpenAIAttachmentsUnknownObject,
                    OpenAIAttachmentsToolOutput
                >
            >;
            const newToolOutput = globals.toolOutput;
            if (newToolOutput?.custom_attachments) {
                const newConverted: MessageAttachment[] = newToolOutput.custom_attachments.map(
                    att => ({
                        type: "custom" as const,
                        data: att.data,
                    })
                );
                setAttachments(newConverted);
            }
        };

        window.addEventListener(SET_GLOBALS_EVENT_TYPE, handleSetGlobals as EventListener);
        return () => {
            window.removeEventListener(SET_GLOBALS_EVENT_TYPE, handleSetGlobals as EventListener);
        };
    }, []);

    return attachments;
}

// Hook to get OpenAI globals if available
export function useOpenAIGlobals() {
    return typeof window !== "undefined" ? window.openai : undefined;
}

// Component that wraps children and provides OpenAI attachments when in ChatGPT context
export function OpenAIAttachmentProvider({
    children,
    opts,
}: {
    children: (attachments: MessageAttachment[]) => ReactNode;
    opts: AttachmentHandlerOpts;
}) {
    const openAIAttachments = useOpenAIAttachments();

    // In OpenAI context, use OpenAI attachments; otherwise, use provided attachments
    const attachments = typeof window !== "undefined" && window.openai ? openAIAttachments : [];

    return <>{children(attachments)}</>;
}

// Wrapper component that merges OpenAI attachments with regular attachments
export function withOpenAIAttachments<P extends { attachments: MessageAttachment[] }>(
    Component: ComponentType<P>
) {
    return function OpenAIAttachmentWrapper(props: P) {
        const openAIAttachments = useOpenAIAttachments();

        // Merge OpenAI attachments with provided attachments
        const mergedAttachments =
            typeof window !== "undefined" && window.openai
                ? [...openAIAttachments, ...props.attachments]
                : props.attachments;

        return <Component {...props} attachments={mergedAttachments} />;
    };
}

// Auto-initialization for standalone ChatGPT context
export function initializeOpenAIStandalone(
    renderContent: (opts: AttachmentHandlerOpts) => ReactNode
) {
    if (typeof window !== "undefined" && window.openai) {
        const init = () => {
            const rootElem = document.getElementById("sierra-widget-root");
            if (rootElem) {
                const root = createRoot(rootElem);
                // Create minimal opts for standalone mode
                const opts: AttachmentHandlerOpts = {
                    containerElement: rootElem,
                    chatRootContainerElement: rootElem,
                    nextHandler: null,
                    sendMessage: (message, attachments) => {
                        // Use OpenAI's sendFollowUpMessage API
                        if (attachments && attachments.length > 0) {
                            console.warn(
                                "Attachments are not supported in OpenAI Apps SDK follow-up messages"
                            );
                        }
                        window.openai!.sendFollowUpMessage({ prompt: message });
                    },
                    canSendMessage: true,
                    setChatInputHidden: () => {
                        // No-op in standalone mode
                    },
                    isLastMessage: true,
                    store: {
                        get: <T,>(key: string): T | undefined => {
                            // Use OpenAI widget state API
                            const widgetState = window.openai!.widgetState;
                            return widgetState?.[key as keyof typeof widgetState] as T | undefined;
                        },
                        set: <T,>(key: string, value: T) => {
                            // Use OpenAI setWidgetState API
                            const currentState = window.openai!.widgetState ?? {};
                            window.openai!.setWidgetState({
                                ...currentState,
                                [key]: value,
                            });
                        },
                    },
                    refreshSecret: async () => false,
                };
                root.render(<>{renderContent(opts)}</>);
            }
        };

        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", init);
        } else {
            init();
        }
    }
}
